package fr.shabbattv;

import android.content.Context;
import android.net.Uri;
import android.util.Base64;

import java.io.File;
import java.io.FileOutputStream;

/**
 * Tiny 2-second H.264/AAC MP4 used by the long Shabbat mode.
 * Both video and audio are silent/black. Keeping a real Media3 playback session active is
 * intentional: Philips' Ambilight screensaver ignored FLAG_KEEP_SCREEN_ON on a static black
 * Activity, while normal video playback is treated as active viewing.
 */
public final class BlackPlaybackAsset {
    private BlackPlaybackAsset() {}

    private static final String BASE64_MP4 =
            "";

    public static Uri uri(Context context) throws Exception {
        File file = new File(context.getCacheDir(), "shabbat-black-loop-v110.mp4");
        if (!file.exists() || file.length() < 3000L) {
            byte[] bytes = Base64.decode(BASE64_MP4, Base64.DEFAULT);
            try (FileOutputStream out = new FileOutputStream(file, false)) {
                out.write(bytes);
                out.flush();
            }
        }
        return Uri.fromFile(file);
    }
}
